This is unnecessarily verbose IMHO. You can simplify it with something like this: 
```suggestion

// Draw the 4 lines
Vector2i corners[4]  = {
    origin,
    origin + Vector2i{ region_size.x, 0 } ,
    origin + region_size,
    origin + Vector2i{ 0, region_size.y } 
 }
for (int i=0; i<4:; i ++) {
    points.push_back(corners[i]);
    points.push_back(corners[(i+1)%4]);
} 
